// `random_pcg.cpp` pulls in `core/os/os.h` -> `core/object/object.h`, which
// needs `gdextension_interface.gen.h` (generated by SCons). The parity harness
// only needs the symbols that `math_funcs.cpp` references, and none of the
// dumped values depend on the RNG, so those three `random()` overloads are
// re-declared here. The generator itself (`pcg32_*`, `rand()`, `randd()`,
// `randf()`) stays untouched: it lives in `random_pcg.h` and is the code under
// test in `tests/parity.rs` via `pcg_sequence`.

#include "core/math/random_pcg.h"

RandomPCG::RandomPCG(uint64_t p_seed, uint64_t p_inc) :
		pcg(), current_inc(p_inc) {
	seed(p_seed);
}

void RandomPCG::randomize() {
	seed(0x9E3779B97F4A7C15ULL);
}

double RandomPCG::random(double p_from, double p_to) {
	return randd() * (p_to - p_from) + p_from;
}

float RandomPCG::random(float p_from, float p_to) {
	return randf() * (p_to - p_from) + p_from;
}

int RandomPCG::random(int p_from, int p_to) {
	if (p_from == p_to) {
		return p_from;
	}
	return p_from;
}
